{
  "investigate": [
    {
      "tool": "sql",
      "query": "SELECT service, used_mb, quota_mb FROM storage WHERE service IN ('invoice-agent', 'payment-service', 'queue', 'workflow')",
      "why": "Check disk usage for other services to identify if disk quota exhaustion is widespread or localized to specific services."
    }
  ],
  "hypotheses": [
    {
      "service": "worker",
      "kind": "bad_deploy",
      "mechanism": "Worker v2.0 deploy introduced a bug causing incorrect disk quota checks or excessive file writes, leading to false disk quota errors.",
      "supporting": ["E14", "E15", "E18", "E33"],
      "refuting": ["E32"],
      "explains": ["M1_throughput_drop", "M2_error_burst", "M3_dead_letters"],
      "repair_plan": [
        {"action": "rollback_service", "params": {"service": "worker"}}
      ]
    },
    {
      "service": "sync-job",
      "kind": "runtime_fault",
      "mechanism": "Sync-job process is stuck in a bad state, causing sync failures despite sufficient disk quota.",
      "supporting": ["E3", "E6", "E16"],
      "refuting": ["E32"],
      "explains": [],
      "repair_plan": [
        {"action": "restart_service", "params": {"service": "sync-job"}}
      ]
    }
  ],
  "summary": "Worker's disk quota errors are likely due to a bad deploy, while sync-job failures are a separate runtime fault."
}
